<?php
declare(strict_types=1);
namespace App;
use PDO;
final class Access{public function __construct(private PDO $db){}public function conference(int $id):array{return self::get($this->db,'SELECT * FROM conferences WHERE id=?',[$id],'conference_not_found');}public function submission(int $id):array{return self::get($this->db,'SELECT * FROM submissions WHERE id=?',[$id],'submission_not_found');}private static function get(PDO $db,string $sql,array $p,string $code):array{$s=$db->prepare($sql);$s->execute($p);$x=$s->fetch();if(!$x)throw new ApiException(404,$code,'Resource not found.');return $x;}public function isChair(int $conferenceId,int $userId):bool{$s=$this->db->prepare('SELECT 1 FROM conference_chairs WHERE conference_id=? AND user_id=?');$s->execute([$conferenceId,$userId]);return(bool)$s->fetchColumn();}public function isAuthor(int $submissionId,int $userId):bool{$s=$this->db->prepare('SELECT 1 FROM submission_authors WHERE submission_id=? AND user_id=?');$s->execute([$submissionId,$userId]);return(bool)$s->fetchColumn();}public function isReviewer(int $submissionId,int $userId):bool{$s=$this->db->prepare('SELECT 1 FROM review_assignments WHERE submission_id=? AND reviewer_id=?');$s->execute([$submissionId,$userId]);return(bool)$s->fetchColumn();}public function requireChair(array $u,int $cid):void{if($u['role']!=='admin'&&!$this->isChair($cid,(int)$u['id']))throw new ApiException(403,'chair_access_required','Conference chair access is required.');}public function requireSubmissionAccess(array $u,array $s):void{if($this->isAuthor((int)$s['id'],(int)$u['id'])||$this->isReviewer((int)$s['id'],(int)$u['id'])||$this->isChair((int)$s['conference_id'],(int)$u['id']))return;throw new ApiException(403,'submission_access_denied','You cannot access this submission.');}public function requirePhase(int $cid,string $phase):void{$c=$this->conference($cid);if($c['active_phase']!==$phase)throw new ApiException(409,'phase_closed',ucfirst($phase).' phase is not active.');}}
